#!/bin/sh
# Entry point of the ros2ebpfd image.
#
# Without a mounted /etc/ros2ebpf/config.yaml the daemon runs with a generated
# minimal configuration: no static shims, discovery on (ROS processes on the
# host or in other containers are found through /proc/<pid>/maps, which needs
# `pid: host`), metrics on 0.0.0.0:9477.
set -e
CFG=/etc/ros2ebpf/config.yaml
if [ "$1" = "ros2ebpfd" ] || [ "$1" = "" ]; then
  if [ ! -f "$CFG" ]; then
    CFG=/run/ros2ebpf/config.yaml
    cat > "$CFG" <<YAML
# generated by entrypoint.sh (no /etc/ros2ebpf/config.yaml mounted)
host: "${ROS2EBPF_HOST:-}"
robot: "${ROS2EBPF_ROBOT:-}"
shims: []
discover_shims: true
topics:
  exclude: [/parameter_events, /rosout]
exporter:
  listen: "${ROS2EBPF_LISTEN:-0.0.0.0:9477}"
control:
  http: "${ROS2EBPF_CONTROL_HTTP:-}"
expectations_file: /etc/ros2ebpf/expectations.yaml
log_level: "${ROS2EBPF_LOG_LEVEL:-info}"
YAML
    echo "entrypoint: using generated $CFG" >&2
  fi
  shift $(( $# > 0 ? 1 : 0 ))
  exec ros2ebpfd -c "$CFG" "$@"
fi
exec "$@"
